package com.ateliercampus.web;
import jakarta.servlet.*;import jakarta.servlet.annotation.WebFilter;import jakarta.servlet.http.*;import java.io.*;import java.security.SecureRandom;import java.util.Base64;
@WebFilter("/*") public class SecuriteFilter implements Filter {private static final SecureRandom RNG=new SecureRandom();public static String token(HttpSession s){synchronized(s){String t=(String)s.getAttribute("csrf");if(t==null){byte[] b=new byte[32];RNG.nextBytes(b);t=Base64.getUrlEncoder().withoutPadding().encodeToString(b);s.setAttribute("csrf",t);}return t;}}
 public void doFilter(ServletRequest req,ServletResponse res,FilterChain chain)throws IOException,ServletException{HttpServletRequest r=(HttpServletRequest)req;HttpServletResponse p=(HttpServletResponse)res;String uri=r.getRequestURI().substring(r.getContextPath().length());Object user=r.getSession(false)==null?null:r.getSession(false).getAttribute("utilisateur");String role=r.getSession(false)==null?null:(String)r.getSession(false).getAttribute("role");boolean manager=uri.startsWith("/gestion/");boolean student=uri.equals("/mes-inscriptions")||uri.equals("/inscription/action");if(manager&&!("GESTIONNAIRE".equals(role))){if(user==null)p.sendRedirect(r.getContextPath()+"/connexion?retour=gestion");else{p.sendError(403,"Accès réservé au gestionnaire.");}return;}if(student&&!("ETUDIANT".equals(role))){if(user==null)p.sendRedirect(r.getContextPath()+"/connexion");else{p.sendError(403,"Opération réservée aux étudiants.");}return;}if("POST".equalsIgnoreCase(r.getMethod())){HttpSession s=r.getSession();String expected=(String)s.getAttribute("csrf"),actual=r.getParameter("csrf");if(expected==null||actual==null||!expected.equals(actual)){p.sendError(403,"Jeton CSRF absent ou invalide.");return;}}p.setHeader("X-Content-Type-Options","nosniff");p.setHeader("X-Frame-Options","DENY");p.setHeader("Referrer-Policy","same-origin");chain.doFilter(req,res);}}
